import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Raggruppamenti possibili per polinomi a cinque termini","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/a_algebra/ad/ad6fb.md","filePath":"lezioni/a_algebra/ad/ad6fb.md"}`),a={name:`lezioni/a_algebra/ad/ad6fb.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="raggruppamenti-possibili-per-polinomi-a-cinque-termini" tabindex="-1">Raggruppamenti possibili per polinomi a cinque termini <a class="header-anchor" href="#raggruppamenti-possibili-per-polinomi-a-cinque-termini" aria-label="Permalink to “Raggruppamenti possibili per polinomi a cinque termini”">​</a></h1><h2 id="alcuni-raggruppamenti-possibili-per-polinomi-a-cinque-termini" tabindex="-1">Alcuni raggruppamenti possibili per polinomi a cinque termini <a class="header-anchor" href="#alcuni-raggruppamenti-possibili-per-polinomi-a-cinque-termini" aria-label="Permalink to “Alcuni raggruppamenti possibili per polinomi a cinque termini”">​</a></h2><p>Qui abbiamo vari casi e bisogna decidere volta per volta cosa fare:</p><p>Ti enumero alcuni dei vari casi possibili per darti un&#39;idea su come procedere:</p><ul><li><a href="./ad6fb1.html">Differenza fra due cubi</a></li><li><a href="./ad6fb2.html">Quadrato di un binomio e raccoglimento</a></li><li><a href="./ad6fb3.html">Trinomio notevole con raccoglimento</a></li></ul><p>Inoltre posso avere somme o differenze di potenze dispari o differenze di potenze pari unite ad una scomposizione a tre termini, quindi i casi diventano piuttosto numerosi e invece che studiarli a memoria conviene cercare di capire volta per volta quale strada seguire.</p><p>Poiché questi raggruppamenti sono piuttosto complicati vengono usati raramente, quindi faremo dei brevi cenni e non considereremo il caso in cui uno dei raggruppamenti sia scomponibile con Ruffini.</p>`,7)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};